ee:message.ee:set-payload:
%dw 2.0
output application/json indent=false
var r = payload[0]
---
if (r == null) { found: false, alertId: vars.alertId }
else {
  found: true,
  alert: { alertId: r.alert_id, raisedOn: r.raised_on, rule: r.rule, detail: r.detail, status: r.status },
  account: { accountId: r.account_id, branch: r.branch, "type": r.account_type, openedOn: r.opened_on },
  customer: {
    customerId: r.customer_id, name: r.name, nameKana: r.name_kana, birthDate: r.birth_date,
    address: r.address, occupation: r.occupation, employer: r.employer,
    declaredAnnualIncomeJpy: r.declared_income, accountPurpose: r.purpose,
    riskRating: r.risk_rating, customerSince: r.customer_since
  }
}

%dw 2.0
output application/json indent=false
---
{
  count: sizeOf(payload),
  transactions: payload map {
    date: $.txn_date, kind: $.kind, amountJpy: $.amount,
    counterparty: $.counterparty, channel: $.channel, memo: $.memo
  }
}

%dw 2.0
output application/json indent=false
var r = payload[0]
---
if (r == null) { found: false, step: "new" }
else {
  found: true, alertId: r.alert_id, step: r.step, recommendation: r.recommendation,
  decision: r.decision, note: r.note, decisionId: r.decision_id, updatedAt: r.updated_at
}

db:insert.db:input-parameters:
#[{
  ctx: payload.contextId, alert: upper(payload.alertId default ''),
  step: payload.step, rec: payload.recommendation
}]

db:update.db:input-parameters:
#[{
  ctx: vars.req.contextId, decision: vars.req.decision,
  note: vars.req.note default '', did: vars.decisionId
}]

#[{
  ctx: vars.req.contextId,
  status: vars.req.decision match {
    case "close" -> "クローズ"
    case "file_str" -> "届出検討"
    else -> "保留"
  }
}]

ee:message.ee:set-payload:
%dw 2.0
output application/json indent=false
---
if (vars.updated > 0) { recorded: true, decisionId: vars.decisionId, decision: vars.req.decision }
else { recorded: false, reason: "no investigation is open for this contextId" }
